    {
      "items": [
        {
          "field": "description",
          "fieldtype": "jira",
          "from_string": "As a Shopper on the EU or EU International storefront, I want to be able to access the EU Declaration of Conformity (DoC) document for sunglasses products, so that I can verify the product meets the required EU lens safety standards.\\n\\nEU regulations require a signed Declaration of Conformity to be accessible for sunglasses sold in the EU market. The document is a signed PDF per style, confirming compliance with ISO 12312-1 and EU Regulation (EU) 2016/425. A link to the relevant PDF should be surfaced on the PDP within the Details and Care tab in the slide-out, for applicable products only.",
          "to_string": "As a Shopper on the EU or EU International storefront, \n\nI want to be able to access the EU Declaration of Conformity (DoC) document for sunglasses products, \n\nso that I can verify the product meets the required EU lens safety standards.\\n\\nEU regulations require a signed Declaration of Conformity to be accessible for sunglasses sold in the EU market. \n\n----\n\nThe document is a signed PDF per style, confirming compliance with ISO 12312-1 and EU Regulation (EU) 2016/425. A link to the relevant PDF should be surfaced on the PDP within the Details and Care tab in the slide-out, for applicable products only."
        }
      ],
      "author": {
        "display_name": "Jasmijn Tsang",
        "name": "Jasmijn Tsang",
        "email": "jasmijn.tsang@accenture.com",
        "avatar_url": "https://avatar-management--avatars.us-west-2.prod.public.atl-paas.net/5cc71886cbbec211ec62929d/40fcd533-06f6-4e5b-ba9f-23879e1193f9/48"
      },
      "created": "2026-08-11T18:00:29.434000+10:00"
    },
    {
      "items": [
        {
          "field": "Acceptance Criteria",
          "fieldtype": "custom",
          "to_string": "1. Given I am on the EU or EU International storefront, when I open the Details & Care slide-out for a sunglasses product that has a DoC PDF associated, then a link to the Declaration of Conformity PDF is displayed within that tab.\n2. Given I click the Declaration of Conformity link, when the action is confirmed, then the PDF opens in a new tab or as a download (TBC with design).\n3. Given a sunglasses product has no DoC PDF associated, when I open the Details & Care slide-out, then no link is displayed.\n4. Given I am on any storefront other than EU or EU International, when I open the Details & Care slide-out, then the Declaration of Conformity link is not displayed regardless of whether a PDF exists.\n5. Given a non-sunglasses product, when I open the Details & Care slide-out on EU or EU International, then the Declaration of Conformity link is not displayed.",
          "to_id": ""
        },
        {
          "field": "Dependency",
          "fieldtype": "custom",
          "to_string": "How is the PDF stored and associated to a product — via a product attribute in BM, a DAM, or another asset management system? This determines whether a separate BM configuration story is needed.\n\nConfirm with design whether the PDF opens in a new tab or downloads directly.\n\nThis requirement is currently being implemented on the existing site — confirm whether the approach taken there should be mirrored on the new site.",
          "to_id": ""
        }
      ],
